class Solution {
public:
    string removeStars(string s) {
        int n = s.length();
        string res = "";
        for(int i=0;i<n;i++){
            if(s[i]=='*') res.erase(res.length()-1, 1);
            else res += s[i];
        }
        return res;

        // Testcase
        // "
    }
};